<?php
defined( 'ABSPATH' ) || exit;
final class SWC_Appointments {
	public function hooks(){add_action('init',array('SWC_Activator','register_type'));add_action('admin_post_swc_submit_appointment',array($this,'precheck'),1);add_action('admin_post_swc_submit_appointment',array($this,'submit'));add_action('admin_post_swc_patient_cancel',array($this,'patient_cancel'));add_action('admin_post_swc_patient_accept_reschedule',array($this,'patient_accept_reschedule'));add_action('admin_post_swc_doctor_update',array($this,'doctor_update'));add_action('admin_post_swc_save_availability',array($this,'save_availability'));}
	public function submit(){if(!is_user_logged_in()){wp_die(esc_html__('Log in to request an appointment.','worldwide-clinic'),'',array('response'=>403));}check_admin_referer('swc_submit_appointment','swc_nonce');$rate='swc_request_'.get_current_user_id();if(absint(get_transient($rate))>=5){wp_die(esc_html__('Please wait before submitting another request.','worldwide-clinic'),'',array('response'=>429));}$doctor=isset($_POST['doctor_id'])?absint($_POST['doctor_id']):0;if(!in_array($doctor,SWC_Helpers::doctor_ids(),true)){wp_die(esc_html__('Choose an available verified doctor.','worldwide-clinic'),'',array('response'=>400));}$mode=isset($_POST['consultation_type'])?sanitize_key(wp_unslash($_POST['consultation_type'])):'';if(!in_array($mode,array('online','in-person'),true)){wp_die(esc_html__('Choose a valid consultation type.','worldwide-clinic'),'',array('response'=>400));}$date=isset($_POST['preferred_date'])?sanitize_text_field(wp_unslash($_POST['preferred_date'])):'';$time=isset($_POST['preferred_time'])?sanitize_text_field(wp_unslash($_POST['preferred_time'])):'';$zone=isset($_POST['patient_timezone'])?sanitize_text_field(wp_unslash($_POST['patient_timezone'])):'UTC';if(!in_array($zone,SWC_Helpers::timezones(),true)){$zone='UTC';}$utc=SWC_Helpers::to_utc($date,$time,$zone);if(!$utc||strtotime($utc)<=time()){wp_die(esc_html__('Choose a valid future date and time.','worldwide-clinic'),'',array('response'=>400));}$phone=isset($_POST['phone'])?SWC_Helpers::phone(wp_unslash($_POST['phone'])):'';$whatsapp=isset($_POST['whatsapp'])?SWC_Helpers::phone(wp_unslash($_POST['whatsapp'])):'';$reason=isset($_POST['reason'])?sanitize_textarea_field(wp_unslash($_POST['reason'])):'';$duration=isset($_POST['duration'])?sanitize_text_field(wp_unslash($_POST['duration'])):'';$country=isset($_POST['country'])?sanitize_text_field(wp_unslash($_POST['country'])):'';$city=isset($_POST['city'])?sanitize_text_field(wp_unslash($_POST['city'])):'';if(!$phone||!$whatsapp||!trim($reason)||empty($_POST['consent'])||empty($_POST['emergency_confirm'])){wp_die(esc_html__('Complete the required contact, reason, and consent fields.','worldwide-clinic'),'',array('response'=>400));}$reason=function_exists('mb_substr')?mb_substr($reason,0,1500):substr($reason,0,1500);$id=wp_insert_post(array('post_type'=>SWC_Helpers::TYPE,'post_status'=>'publish','post_title'=>'Appointment Request — '.current_time('Y-m-d H:i'),'post_author'=>get_current_user_id()),true);if(is_wp_error($id)){wp_die(esc_html__('The request could not be saved.','worldwide-clinic'),'',array('response'=>500));}$meta=array('doctor_id'=>$doctor,'status'=>'requested','consultation_type'=>$mode,'preferred_at_utc'=>$utc,'patient_timezone'=>$zone,'country'=>$country,'city'=>$city,'phone'=>$phone,'whatsapp'=>$whatsapp,'reason'=>$reason,'duration'=>$duration,'consent_at'=>current_time('mysql',true));foreach($meta as $k=>$v){update_post_meta($id,'_swc_'.$k,$v);}SWC_Helpers::audit($id,'requested','');set_transient($rate,absint(get_transient($rate))+1,HOUR_IN_SECONDS);$this->notify($id,'A new appointment request has been received.');$p=SWC_Helpers::pages();wp_safe_redirect(add_query_arg('requested','1',!empty($p['patient'])?get_permalink($p['patient']):home_url('/')));exit;}
	public function patient_cancel(){if(!is_user_logged_in()){wp_die(esc_html__('Access denied.','worldwide-clinic'),'',array('response'=>403));}$id=isset($_POST['appointment_id'])?absint($_POST['appointment_id']):0;check_admin_referer('swc_patient_cancel_'.$id);if(!SWC_Helpers::can_patient_manage($id)||in_array(SWC_Helpers::status($id),array('completed','cancelled'),true)){wp_die(esc_html__('This appointment cannot be cancelled.','worldwide-clinic'),'',array('response'=>403));}update_post_meta($id,'_swc_status','cancelled');SWC_Helpers::audit($id,'cancelled','Cancelled by patient');$this->notify($id,'An appointment request was cancelled.');$p=SWC_Helpers::pages();wp_safe_redirect(!empty($p['patient'])?get_permalink($p['patient']):home_url('/'));exit;}
	public function doctor_update(){if(!is_user_logged_in()){wp_die(esc_html__('Access denied.','worldwide-clinic'),'',array('response'=>403));}$id=isset($_POST['appointment_id'])?absint($_POST['appointment_id']):0;check_admin_referer('swc_doctor_update_'.$id);if(!SWC_Helpers::can_doctor_manage($id)){wp_die(esc_html__('You cannot manage this appointment.','worldwide-clinic'),'',array('response'=>403));}$status=isset($_POST['status'])?sanitize_key(wp_unslash($_POST['status'])):'';if(!in_array($status,array('under-review','accepted','reschedule-requested','declined','completed'),true)){wp_die(esc_html__('Invalid appointment status.','worldwide-clinic'),'',array('response'=>400));}$note=isset($_POST['doctor_note'])?sanitize_textarea_field(wp_unslash($_POST['doctor_note'])):'';if('reschedule-requested'===$status){$date=isset($_POST['new_date'])?sanitize_text_field(wp_unslash($_POST['new_date'])):'';$time=isset($_POST['new_time'])?sanitize_text_field(wp_unslash($_POST['new_time'])):'';$zone=isset($_POST['new_timezone'])?sanitize_text_field(wp_unslash($_POST['new_timezone'])):'UTC';if(!in_array($zone,SWC_Helpers::timezones(),true)){$zone='UTC';}$new=SWC_Helpers::to_utc($date,$time,$zone);if(!$new||strtotime($new)<=time()){wp_die(esc_html__('Provide a valid future reschedule time.','worldwide-clinic'),'',array('response'=>400));}update_post_meta($id,'_swc_proposed_at_utc',$new);update_post_meta($id,'_swc_proposed_timezone',$zone);}update_post_meta($id,'_swc_status',$status);update_post_meta($id,'_swc_doctor_note',$note);SWC_Helpers::audit($id,$status,$note);$this->notify($id,'Your appointment status was updated to '.SWC_Helpers::statuses()[$status].'.');$p=SWC_Helpers::pages();wp_safe_redirect(!empty($p['doctor'])?get_permalink($p['doctor']):home_url('/'));exit;}
	public function save_availability(){if(!is_user_logged_in()||!SDD_Helpers::is_verified(get_current_user_id())){wp_die(esc_html__('Verified doctor access is required.','worldwide-clinic'),'',array('response'=>403));}check_admin_referer('swc_save_availability','swc_nonce');$id=get_current_user_id();$days=isset($_POST['days'])?array_intersect(array_map('sanitize_key',(array)wp_unslash($_POST['days'])),array('monday','tuesday','wednesday','thursday','friday','saturday','sunday')):array();$zone=isset($_POST['timezone'])?sanitize_text_field(wp_unslash($_POST['timezone'])):'UTC';if(!in_array($zone,SWC_Helpers::timezones(),true)){$zone='UTC';}update_user_meta($id,'_swc_available_days',array_values($days));update_user_meta($id,'_swc_start_time',isset($_POST['start_time'])?sanitize_text_field(wp_unslash($_POST['start_time'])):'');update_user_meta($id,'_swc_end_time',isset($_POST['end_time'])?sanitize_text_field(wp_unslash($_POST['end_time'])):'');update_user_meta($id,'_swc_timezone',$zone);update_user_meta($id,'_swc_duration',min(180,max(10,isset($_POST['duration'])?absint($_POST['duration']):30)));foreach(array('online','in_person','accepting','unavailable') as $key){update_user_meta($id,'_swc_'.$key,isset($_POST[$key])?'1':'0');}$p=SWC_Helpers::pages();wp_safe_redirect(add_query_arg('updated','1',!empty($p['availability'])?get_permalink($p['availability']):home_url('/')));exit;}
	public function precheck(){ $doctor=isset($_POST['doctor_id'])?absint($_POST['doctor_id']):0; $mode=isset($_POST['consultation_type'])?sanitize_key(wp_unslash($_POST['consultation_type'])):''; if($doctor&&('1'===SWC_Helpers::doctor_meta($doctor,'unavailable','0')||'1'!==SWC_Helpers::doctor_meta($doctor,'accepting','0'))){wp_die(esc_html__('The selected doctor is not accepting appointment requests.','worldwide-clinic'),'',array('response'=>400));} if($doctor&&'online'===$mode&&'1'!==SWC_Helpers::doctor_meta($doctor,'online','0')){wp_die(esc_html__('The selected doctor has not enabled online consultation.','worldwide-clinic'),'',array('response'=>400));} if($doctor&&'in-person'===$mode&&'1'!==SWC_Helpers::doctor_meta($doctor,'in_person','0')){wp_die(esc_html__('The selected doctor has not enabled in-person consultation.','worldwide-clinic'),'',array('response'=>400));} }
	public function patient_accept_reschedule(){if(!is_user_logged_in()){wp_die(esc_html__('Access denied.','worldwide-clinic'),'',array('response'=>403));}$id=isset($_POST['appointment_id'])?absint($_POST['appointment_id']):0;check_admin_referer('swc_patient_accept_'.$id);if(!SWC_Helpers::can_patient_manage($id)||'reschedule-requested'!==SWC_Helpers::status($id)){wp_die(esc_html__('This reschedule cannot be accepted.','worldwide-clinic'),'',array('response'=>403));}$proposed=SWC_Helpers::meta($id,'proposed_at_utc');if(!$proposed){wp_die(esc_html__('No proposed time was found.','worldwide-clinic'),'',array('response'=>400));}update_post_meta($id,'_swc_preferred_at_utc',$proposed);update_post_meta($id,'_swc_status','accepted');SWC_Helpers::audit($id,'reschedule-accepted','Accepted by patient');$this->notify($id,'The proposed appointment time was accepted.');$p=SWC_Helpers::pages();wp_safe_redirect(!empty($p['patient'])?get_permalink($p['patient']):home_url('/'));exit;}
	private function notify($id,$message){$patient=get_userdata(absint(get_post_field('post_author',$id)));$doctor=get_userdata(absint(SWC_Helpers::meta($id,'doctor_id')));$subject='Worldwide Clinic Appointment Update';$body=$message."\n\nAppointment reference: ".$id."\nDo not send sensitive medical information by email.";if($patient&&is_email($patient->user_email)){wp_mail($patient->user_email,$subject,$body);}if($doctor&&is_email($doctor->user_email)){wp_mail($doctor->user_email,$subject,$body);}}
}
